[
  {"name": "blank-exit", "guard": "blank", "steps": ["const_empty"], "fallback": "full", "rationale": "Whitespace-only strings strip to '' under the reference too, so we can skip nfkc+casefold entirely and return the empty string immediately."},
  {"name": "clean-ascii-identity", "guard": "clean_ascii", "steps": ["ws_collapse"], "fallback": "full", "rationale": "Guaranteed-normalized lowercase ASCII with single inner spaces needs neither nfkc nor casefold; one str split/join reproduces the output."},
  {"name": "latin1-lower-bet", "guard": "latin1", "steps": ["nfkc", "lower", "ws_collapse"], "fallback": "full", "rationale": "Bet that NFKC already expands the only casefold-lower divergences in Latin-1 range (e.g. sharp s handling after normalization) so cheaper lower suffices on the ord<256 path."}
]

[
  {
    "name": "fast_clean_ascii",
    "guard": "clean_ascii",
    "steps": ["identity"],
    "fallback": "full",
    "rationale": "If the string is already ASCII and normalized, return it unchanged, skipping all heavy operations."
  },
  {
    "name": "ascii_fast_path",
    "guard": "ascii",
    "steps": ["bytes_lower", "map_fs_controls", "bytes_ws_collapse"],
    "fallback": "full",
    "rationale": "For any ASCII input, lower‑case, map control characters to space and collapse whitespace using cheap byte ops."
  },
  {
    "name": "latin1_nfc_fast",
    "guard": "latin1",
    "steps": ["nfc", "casefold", "ws_collapse"],
    "fallback": "full",
    "rationale": "Latin‑1 characters never need compatibility decomposition, so replace NFKC with the cheaper NFC."
  }
]

[
  {
    "name": "latin1-casefold-first",
    "guard": "latin1",
    "steps": ["casefold", "nfkc", "ws_collapse"],
    "fallback": "full",
    "rationale": "On Latin-1 inputs casefold then NFKC yields identical results to NFKC then casefold but allows earlier folding."
  },
  {
    "name": "clean-ascii-fast",
    "guard": "clean_ascii",
    "steps": ["identity"],
    "fallback": {
      "name": "ascii-map-lower",
      "guard": "ascii",
      "steps": ["map_fs_controls", "bytes_lower", "bytes_ws_collapse"],
      "fallback": "full",
      "rationale": "ASCII fast path uses cheaper byte ops instead of NFKC/casefold."
    },
    "rationale": "Already-normalized ASCII passes through untouched; others use byte-level ASCII route."
  },
  {
    "name": "nfc-for-ascii",
    "guard": "ascii",
    "steps": ["map_fs_controls", "lower", "ws_collapse"],
    "fallback": "full",
    "rationale": "ASCII never needs NFKC so lower+ws_collapse replaces NFKC+casefold exactly."
  }
]
